SELECT setval(pg_get_serial_sequence('product_model','id'),(SELECT max(id) FROM product_model));
SELECT setval(pg_get_serial_sequence('part','id'),(SELECT max(id) FROM part));
SELECT setval(pg_get_serial_sequence('warehouse','id'),(SELECT max(id) FROM warehouse));
SELECT setval(pg_get_serial_sequence('factory','id'),(SELECT max(id) FROM factory));
SELECT setval(pg_get_serial_sequence('part_lot','id'),(SELECT max(id) FROM part_lot));
SELECT setval(pg_get_serial_sequence('product','id'),(SELECT max(id) FROM product));
SELECT setval(pg_get_serial_sequence('product_component','id'),(SELECT max(id) FROM product_component));

-- [통합] 접수 API는 firmware 필수인데 제품 정보에 없어서 프론트 접수가 400으로 실패했다
UPDATE product SET information=information||'{"firmware":"1.0.3"}'::jsonb WHERE NOT information ? 'firmware';

